"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type AnalyticsFunnelElementId,
  analyticsFunnelTimeline,
  DEFAULT_STEPS,
  type FunnelStep,
} from "./timeline";

export type { FunnelStep };

const { fontFamily: geist } = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

export interface FunnelBreakdownRow {
  label: string;
  share: number;
}

export interface AnalyticsFunnelProps {
  steps?: FunnelStep[];
  title?: string;
  variantLabel?: string;
  tooltipStep?: number;
  breakdown?: FunnelBreakdownRow[];
  dateRange?: string;
  /** Label above the total conversion figure in landscape. */
  totalLabel?: string;
  /** Legend label of the chart before the variant is switched on. */
  allUsersLabel?: string;
  /** Legend label of the dashed control line. */
  controlLabel?: string;
  theme?: "light" | "dark";
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Size of the dashboard, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /**
   * Moves, trims or stretches the panel, single bars and morphs, the
   * cursor's moves, the badge, the tooltip and the camera, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<AnalyticsFunnelElementId>;
}

const DEFAULT_BREAKDOWN: FunnelBreakdownRow[] = [
  { label: "Web", share: 0.61 },
  { label: "iOS", share: 0.26 },
  { label: "Android", share: 0.13 },
];

const CL = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const enterEase = Easing.bezier(0.32, 0.72, 0, 1);
const exitEase = Easing.bezier(0.55, 0, 1, 0.45);
const camEase = Easing.bezier(0.87, 0, 0.13, 1);
const tween = (f: number, a: number, b: number, easing = enterEase) =>
  interpolate(f, [a, b], [0, 1], { ...CL, easing });
const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const fmt = (n: number) =>
  String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const pct = (v: number) => `${v.toFixed(1)}%`;

const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const MORPH = { damping: 200 };

function withAlpha(color: string, alpha: number) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? hex.replace(/(.)/g, "$1$1") : hex;
  if (!/^[0-9a-fA-F]{6}$/.test(full)) return color;
  const n = Number.parseInt(full, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
}

interface Pal {
  win: string;
  tip: string;
  line: string;
  track: string;
  text: string;
  muted: string;
  faint: string;
  green: string;
  greenBg: string;
  knobOff: string;
  scrim: string;
  winShadow: string;
  tipShadow: string;
  stageText: string;
  stageMuted: string;
  dark: boolean;
}

function palette(theme: "light" | "dark"): Pal {
  return theme === "dark"
    ? {
        win: "#0E0F12",
        tip: "#17181C",
        line: "rgba(255,255,255,0.07)",
        track: "rgba(255,255,255,0.08)",
        text: "#EEEEF0",
        muted: "rgba(238,238,240,0.6)",
        faint: "rgba(238,238,240,0.4)",
        green: "#62D893",
        greenBg: "rgba(98,216,147,0.12)",
        knobOff: "rgba(255,255,255,0.16)",
        scrim: "rgba(3,4,10,0.28)",
        winShadow:
          "0 0 0 1px rgba(255,255,255,0.09), inset 0 1px 0 rgba(255,255,255,0.05), 0 40px 90px -24px rgba(0,0,0,0.75), 0 10px 28px rgba(0,0,0,0.35)",
        tipShadow:
          "0 0 0 1px rgba(255,255,255,0.11), inset 0 1px 0 rgba(255,255,255,0.06), 0 24px 48px -12px rgba(0,0,0,0.7)",
        stageText: "#F2F2F4",
        stageMuted: "rgba(242,242,244,0.62)",
        dark: true,
      }
    : {
        win: "#FCFCFB",
        tip: "#FFFFFF",
        line: "rgba(22,23,26,0.08)",
        track: "rgba(22,23,26,0.07)",
        text: "#16171A",
        muted: "rgba(22,23,26,0.6)",
        faint: "rgba(22,23,26,0.42)",
        green: "#18794E",
        greenBg: "rgba(24,121,78,0.1)",
        knobOff: "rgba(22,23,26,0.16)",
        scrim: "rgba(238,240,246,0.18)",
        winShadow:
          "0 0 0 1px rgba(17,19,24,0.07), 0 1px 2px rgba(17,19,24,0.05), 0 30px 70px -20px rgba(28,38,92,0.28)",
        tipShadow:
          "0 0 0 1px rgba(17,19,24,0.08), 0 2px 4px rgba(17,19,24,0.05), 0 22px 44px -14px rgba(28,38,92,0.3)",
        stageText: "#14151A",
        stageMuted: "rgba(20,21,26,0.6)",
        dark: false,
      };
}

const ICONS = {
  arrowUp: "M8 12.5v-9M4.5 7 8 3.5 11.5 7",
  calendar: "M3.25 4h9.5v9.25h-9.5zM3.25 6.75h9.5M5.75 2.5v2.75M10.25 2.5v2.75",
} as const;

function Icon({
  name,
  color,
  size = 16,
}: {
  name: keyof typeof ICONS;
  color: string;
  size?: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      style={{ flexShrink: 0, display: "block" }}
    >
      <path
        d={ICONS[name]}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * Laid out at `rest`; the ride from (x, y) is a transform, since layout
 * rounds the box to whole pixels and a cursor eased by `left`/`top` steps.
 */
function Cursor({
  x,
  y,
  rest,
  scale,
}: {
  x: number;
  y: number;
  rest: { x: number; y: number };
  scale: number;
}) {
  return (
    <svg
      width={24}
      height={28}
      viewBox="0 0 20 24"
      style={{
        position: "absolute",
        left: rest.x - 2,
        top: rest.y - 2,
        transformOrigin: "2px 2px",
        transform: `translate(${x - rest.x}px, ${y - rest.y}px) scale(${scale})`,
        filter: "drop-shadow(0 3px 6px rgba(0,0,0,0.3))",
        overflow: "visible",
      }}
    >
      <path
        d="M2 2 L2 19.5 L6.6 15.4 L9.8 22.4 L12.9 21 L9.8 14.2 L16 14.2 Z"
        fill="#FFFFFF"
        stroke="#16171A"
        strokeWidth={1.1}
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function AnalyticsFunnel(props: AnalyticsFunnelProps) {
  const {
    steps = DEFAULT_STEPS,
    title = "Activation funnel",
    variantLabel = "New onboarding",
    tooltipStep = 2,
    breakdown = DEFAULT_BREAKDOWN,
    dateRange = "Last 30 days",
    totalLabel = "Total conversion",
    allUsersLabel = "All users",
    controlLabel = "Control",
    theme = "light",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = geist,
    scale = 1,
    delay = 0,
    speed = 1,
    ground,
    groundParams,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    analyticsFunnelTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const panel = tl.get("panel");
  const camera = tl.get("camera");
  const cursorEl = tl.get("cursor");
  const clickEl = tl.get("click");
  const hoverEl = tl.get("hover");
  const badgeAt = tl.get("badge");
  const tipEl = tl.get("tip");
  const leave = tl.get("leave");
  const themePal = palette(theme);
  const pal: Pal = ink ? { ...themePal, text: ink, stageText: ink } : themePal;
  const tall = H > W * 1.2;
  const D = tall ? { w: 800, h: 1422 } : { w: 1280, h: 720 };
  const s = Math.min(W / D.w, H / D.h);
  const sp = (at: number, config: object) =>
    spring({ frame: frame - at, fps, config });

  const WIN = tall
    ? { x: 40, y: 330, w: 720, h: 1000 }
    : { x: 156, y: 60, w: 968, h: 600 };
  const PAD = tall ? 28 : 32;
  const HEAD_H = 76;
  const KPI_Y = HEAD_H + 22;
  const CT = tall ? HEAD_H + 112 : KPI_Y + 112;
  const AXIS_W = 52;
  const PLOT = {
    x: PAD + AXIS_W,
    y: CT + 62,
    w: WIN.w - PAD * 2 - AXIS_W,
    h: WIN.h - PAD - 64 - (CT + 62),
  };
  const n = steps.length;
  const slot = PLOT.w / n;
  const BAR_W = Math.min(124, slot * 0.58);
  const colX = (i: number) => PLOT.x + slot * i + (slot - BAR_W) / 2;
  const yOf = (p: number) => PLOT.y + PLOT.h * (1 - p / 100);

  const morphEls = steps.map((_, i) => tl.get(`morph:${i}`));
  const barEls = steps.map((_, i) => tl.get(`bar:${i}`));
  const morph = morphEls.map((e) => sp(e.start, MORPH));
  const value = (i: number) =>
    lerp(steps[i].control, steps[i].variant, morph[i]);
  const first = value(0) || 1;
  const ofFirst = (i: number) => (value(i) / first) * 100;
  const fromPrev = (i: number) =>
    i === 0 ? 100 : (value(i) / value(i - 1)) * 100;
  const grow = barEls.map((e) => sp(e.start, CARD));
  const totalC = (steps[n - 1].control / steps[0].control) * 100;
  const totalV = (steps[n - 1].variant / steps[0].variant) * 100;
  const uplift = Math.round(((totalV - totalC) / totalC) * 100);
  const totalNow = lerp(totalC, totalV, morph[n - 1]);

  const win = sp(panel.start, HEAVY);
  const winA = tween(frame, panel.start, panel.end);
  const toggleOn = sp(clickEl.start + clickEl.beat("toggleAt"), CHIP);
  const on = toggleOn > 0.5;
  const badge = sp(badgeAt.start, CHIP);
  const tip = sp(tipEl.start, CARD);
  const tipA = tween(frame, tipEl.start, tipEl.end);
  const tt = clamp(tooltipStep, 0, n - 1);
  const cam = tween(frame, camera.start, camera.end, camEase);
  // The window springs in until the camera push takes over, and the push runs
  // to the last frame, so the foreground never stands still in between.
  const moving = frame > panel.start && frame < camera.end;

  const TOG_W = 236;
  const togX = WIN.w - PAD - TOG_W;
  const togglePt = { x: WIN.x + togX + 14 + 18, y: WIN.y + HEAD_H / 2 + 4 };
  const hoverPt = {
    x: WIN.x + colX(tt) + BAR_W * 0.6,
    y: WIN.y + yOf(ofFirst(tt) * 0.55),
  };
  // hoverPt follows the bar while it morphs; the cursor is laid out where
  // that bar ends, so its box never moves by layout
  const cursorRest = {
    x: hoverPt.x,
    y: WIN.y + yOf((steps[tt].variant / (steps[0].variant || 1)) * 100 * 0.55),
  };
  const startPt = { x: D.w * 0.86, y: D.h + 40 };
  const leg1 = sp(cursorEl.start, HEAVY);
  const leg2 = sp(hoverEl.start, HEAVY);
  const arc = (
    a: { x: number; y: number },
    b: { x: number; y: number },
    p: number,
  ) => {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const d = Math.hypot(dx, dy) || 1;
    const bow = Math.sin(clamp(p, 0, 1) * Math.PI) * Math.min(60, d * 0.18);
    return {
      x: lerp(a.x, b.x, p) + (dy / d) * bow,
      y: lerp(a.y, b.y, p) - (dx / d) * bow,
    };
  };
  const cur =
    frame < hoverEl.start
      ? arc(startPt, togglePt, leg1)
      : arc(togglePt, hoverPt, leg2);
  const press =
    sp(clickEl.start + clickEl.beat("pressAt"), CHIP) -
    sp(clickEl.start + clickEl.beat("toggleAt"), CHIP);
  const cursorScale = 1 - 0.04 * clamp(press, 0, 1.2);
  const cursorA =
    tween(frame, cursorEl.start, cursorEl.end) *
    (1 - tween(frame, leave.start, leave.end, exitEase));

  const tint = withAlpha(accent, pal.dark ? 0.16 : 0.1);
  const labelInk = (t: number) => (t > 0.5 ? pal.text : pal.muted);

  const stat = (label: string, val: React.ReactNode, i: number) => {
    const a = tween(
      frame,
      panel.start + panel.beat("statAt") + i * panel.beat("statStep"),
      panel.start + panel.beat("statEnd") + i * panel.beat("statStep"),
    );
    return (
      <div
        style={{
          paddingLeft: tall && i === 0 ? 0 : 24,
          borderLeft: tall && i === 0 ? "none" : `1px solid ${pal.line}`,
          opacity: a,
          transform: `translateY(${(1 - a) * 8}px)`,
          flex: tall ? 1 : undefined,
        }}
      >
        <div style={{ fontSize: 16, color: pal.muted }}>{label}</div>
        <div
          style={{
            fontSize: 26,
            fontWeight: 300,
            color: pal.text,
            marginTop: 6,
            letterSpacing: "-0.02em",
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {val}
        </div>
      </div>
    );
  };

  const badgeEl = (size: number) => (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        height: size * 1.75,
        padding: `0 ${size * 0.55}px 0 ${size * 0.4}px`,
        borderRadius: 8,
        background: pal.greenBg,
        color: pal.green,
        fontSize: size,
        fontVariantNumeric: "tabular-nums",
        opacity: clamp(badge * 2, 0, 1),
        transform: `translateY(${(1 - badge) * 10}px) scale(${0.85 + 0.15 * badge})`,
        transformOrigin: "0% 50%",
        whiteSpace: "nowrap",
      }}
    >
      <Icon name="arrowUp" color={pal.green} size={size} />
      {uplift > 0 ? "+" : ""}
      {uplift}%
    </span>
  );

  const tipW = tall ? 312 : 264;
  const tipX = PLOT.x + PLOT.w - tipW + 8;
  const tipY = tall ? PLOT.y - 8 : PLOT.y - 20;
  const rowH = tall ? 32 : 26;
  const stepV = value(tt);

  return (
    <AbsoluteFill
      style={{
        fontFamily,
        fontWeight: 400,
        overflow: "hidden",
        WebkitFontSmoothing: "antialiased",
        background:
          background === undefined
            ? pal.dark
              ? "#03050C"
              : "#EEF0F6"
            : background === "transparent"
              ? undefined
              : background,
      }}
    >
      {background === undefined ? (
        <>
          <GshGround
            preset={ground ?? (pal.dark ? "film-blue" : "glasswork")}
            params={groundParams}
            timeOffset={pal.dark ? 4 : 3}
            timeScale={0.3}
          />
          <AbsoluteFill style={{ background: pal.scrim }} />
        </>
      ) : null}
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: (W - D.w * s) / 2,
            top: (H - D.h * s) / 2,
            width: D.w,
            height: D.h,
            transformOrigin: "0 0",
            transform: `scale(${s})`,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              transformOrigin: `${WIN.x + tipX}px ${WIN.y + tipY + 120}px`,
              transform: `scale(${1 + 0.035 * cam})${glide(moving)}`,
            }}
          >
            {tall ? (
              <div
                style={{ position: "absolute", left: 48, top: 92, right: 48 }}
              >
                <div
                  style={{
                    fontSize: 24,
                    color: pal.stageMuted,
                    opacity: tween(
                      frame,
                      panel.start + panel.beat("headAt"),
                      panel.start + panel.beat("headEnd"),
                    ),
                  }}
                >
                  Paid conversion · {dateRange.toLowerCase()}
                </div>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 22,
                    marginTop: 10,
                    overflow: "hidden",
                  }}
                >
                  <span
                    style={{
                      fontSize: 132,
                      fontWeight: 300,
                      letterSpacing: "-0.045em",
                      lineHeight: 1.05,
                      color: pal.stageText,
                      fontVariantNumeric: "tabular-nums",
                      transform: `translateY(${(1 - tween(frame, panel.start + panel.beat("bigAt"), panel.start + panel.beat("bigEnd"))) * 100}%)`,
                    }}
                  >
                    {pct(totalNow)}
                  </span>
                  {badgeEl(30)}
                </div>
              </div>
            ) : null}
            <div
              style={{
                position: "absolute",
                left: WIN.x,
                top: WIN.y,
                width: WIN.w,
                height: WIN.h,
                opacity: winA,
                transform: `translateY(${(1 - win) * 48}px) scale(${0.97 + 0.03 * win})`,
                transformOrigin: "50% 100%",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  borderRadius: 16,
                  background: pal.win,
                  boxShadow: pal.winShadow,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: HEAD_H,
                    display: "flex",
                    alignItems: "center",
                    gap: 14,
                    padding: `0 ${PAD}px`,
                    borderBottom: `1px solid ${pal.line}`,
                  }}
                >
                  <span
                    style={{
                      fontSize: 20,
                      color: pal.text,
                      letterSpacing: "-0.01em",
                    }}
                  >
                    {tall ? "Funnel" : title}
                  </span>
                  <span
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      fontSize: 16,
                      color: pal.muted,
                    }}
                  >
                    <Icon name="calendar" color={pal.faint} />
                    {dateRange}
                  </span>
                  <div style={{ flex: 1 }} />
                  <div
                    style={{
                      width: TOG_W,
                      height: 40,
                      boxSizing: "border-box",
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                      padding: "0 14px",
                      borderRadius: 10,
                      background: on
                        ? withAlpha(accent, pal.dark ? 0.14 : 0.07)
                        : "transparent",
                      boxShadow: `inset 0 0 0 1px ${on ? withAlpha(accent, 0.4) : pal.line}`,
                      transform: `scale(${1 - 0.04 * clamp(press, 0, 1.2)})`,
                    }}
                  >
                    <div
                      style={{
                        width: 36,
                        height: 22,
                        borderRadius: 99,
                        position: "relative",
                        flexShrink: 0,
                        background: on ? accent : pal.knobOff,
                      }}
                    >
                      <div
                        style={{
                          position: "absolute",
                          top: 3,
                          // laid out where the switch lands; the slide
                          // there is a transform, as with the cursor
                          left: 17,
                          transform: `translateX(${(toggleOn - 1) * 14}px)`,
                          width: 16,
                          height: 16,
                          borderRadius: 99,
                          background: "#fff",
                          boxShadow: "0 1px 2px rgba(0,0,0,0.25)",
                        }}
                      />
                    </div>
                    <span style={{ fontSize: 16, color: pal.text }}>
                      {variantLabel}
                    </span>
                  </div>
                </div>

                {!tall ? (
                  <div
                    style={{
                      position: "absolute",
                      left: PAD,
                      right: PAD,
                      top: KPI_Y,
                      display: "flex",
                      alignItems: "flex-end",
                      gap: 24,
                    }}
                  >
                    <div>
                      <div style={{ fontSize: 16, color: pal.muted }}>
                        {totalLabel}
                      </div>
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 14,
                          marginTop: 2,
                          overflow: "hidden",
                        }}
                      >
                        <span
                          style={{
                            fontSize: 54,
                            fontWeight: 300,
                            letterSpacing: "-0.04em",
                            color: pal.text,
                            fontVariantNumeric: "tabular-nums",
                            lineHeight: 1.1,
                            transform: `translateY(${(1 - tween(frame, panel.start + panel.beat("totalAt"), panel.start + panel.beat("totalEnd"))) * 100}%)`,
                          }}
                        >
                          {pct(totalNow)}
                        </span>
                        {badgeEl(18)}
                      </div>
                    </div>
                    <div style={{ flex: 1 }} />
                    {stat("Visits", fmt(value(0)), 0)}
                    {stat("Paying users", fmt(value(n - 1)), 1)}
                    {stat(
                      "Time to pay",
                      morph[n - 1] > 0.5 ? "1d 19h" : "2d 6h",
                      2,
                    )}
                  </div>
                ) : (
                  <div
                    style={{
                      position: "absolute",
                      left: PAD,
                      right: PAD,
                      top: HEAD_H + 20,
                      display: "flex",
                      gap: 24,
                    }}
                  >
                    {stat("Visits", fmt(value(0)), 0)}
                    {stat("Paying users", fmt(value(n - 1)), 1)}
                    {stat(
                      "Time to pay",
                      morph[n - 1] > 0.5 ? "1d 19h" : "2d 6h",
                      2,
                    )}
                  </div>
                )}

                <div
                  style={{
                    position: "absolute",
                    left: PAD,
                    right: PAD,
                    top: CT,
                    height: 1,
                    background: pal.line,
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    left: PAD,
                    right: PAD,
                    top: CT + 18,
                    display: "flex",
                    alignItems: "center",
                    gap: 22,
                    justifyContent: "flex-end",
                    fontSize: 16,
                    color: pal.muted,
                  }}
                >
                  <span
                    style={{ display: "flex", alignItems: "center", gap: 8 }}
                  >
                    <span
                      style={{
                        width: 10,
                        height: 10,
                        borderRadius: 3,
                        background: accent,
                      }}
                    />
                    {on ? variantLabel : allUsersLabel}
                  </span>
                  <span
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      opacity: tween(
                        frame,
                        morphEls[0].start + morphEls[0].beat("legendAt"),
                        morphEls[0].start + morphEls[0].beat("legendEnd"),
                      ),
                    }}
                  >
                    <span
                      style={{
                        width: 16,
                        borderTop: `1.5px dashed ${pal.faint}`,
                      }}
                    />
                    {controlLabel}
                  </span>
                </div>

                <svg
                  width={WIN.w}
                  height={WIN.h}
                  style={{ position: "absolute", left: 0, top: 0 }}
                >
                  {[0, 50, 100].map((g) => (
                    <g key={g}>
                      <line
                        x1={PLOT.x}
                        x2={PLOT.x + PLOT.w}
                        y1={yOf(g)}
                        y2={yOf(g)}
                        stroke={pal.line}
                        strokeDasharray={g ? "2 5" : undefined}
                      />
                      <text
                        x={PLOT.x - 14}
                        y={yOf(g) + 5}
                        textAnchor="end"
                        fontSize={15}
                        fill={pal.faint}
                        fontFamily={fontFamily}
                        style={{ fontVariantNumeric: "tabular-nums" }}
                      >
                        {g}%
                      </text>
                    </g>
                  ))}
                  <rect
                    x={colX(tt) - 12}
                    y={PLOT.y - 6}
                    width={BAR_W + 24}
                    height={yOf(0) - PLOT.y + 6}
                    rx={10}
                    fill={pal.track}
                    opacity={tipA * 0.7}
                  />
                  {steps.map((st, i) => {
                    const g = grow[i];
                    const x = colX(i);
                    const prev = i === 0 ? 100 : ofFirst(i - 1);
                    const curP = ofFirst(i);
                    const ctrl = (st.control / steps[0].control) * 100;
                    const top = yOf(prev * g);
                    const bar = yOf(curP * g);
                    const dim = i === tt ? 0 : tipA;
                    const ghost =
                      i > 0
                        ? tween(
                            frame,
                            morphEls[i].start + morphEls[i].beat("ghostAt"),
                            morphEls[i].start + morphEls[i].beat("ghostEnd"),
                          )
                        : 0;
                    return (
                      <g key={st.label}>
                        <rect
                          x={x}
                          y={top}
                          width={BAR_W}
                          height={Math.max(0, bar - top)}
                          rx={6}
                          fill={tint}
                        />
                        <rect
                          x={x}
                          y={bar}
                          width={BAR_W}
                          height={Math.max(0, yOf(0) - bar)}
                          rx={6}
                          fill={accent}
                          opacity={1 - 0.3 * dim}
                        />
                        {ghost > 0 && Math.abs(ctrl - curP) > 0.3 ? (
                          <line
                            x1={x - 8}
                            x2={lerp(x - 8, x + BAR_W + 8, ghost)}
                            y1={yOf(ctrl)}
                            y2={yOf(ctrl)}
                            stroke={pal.dark ? "#FFFFFF" : "#16171A"}
                            strokeOpacity={0.7}
                            strokeWidth={1.5}
                            strokeDasharray="4 4"
                          />
                        ) : null}
                      </g>
                    );
                  })}
                </svg>

                {steps.map((st, i) => {
                  const x = colX(i);
                  // Laid out over the bar it ends on; its rise with the bar
                  // is a transform, as with the cursor.
                  const labTop =
                    yOf((steps[i].variant / (steps[0].variant || 1)) * 100) -
                    30;
                  const labRise = yOf(ofFirst(i) * grow[i]) - 30 - labTop;
                  const lab = tween(
                    frame,
                    barEls[i].start + barEls[i].beat("labelAt"),
                    barEls[i].end,
                  );
                  return (
                    <div key={st.label}>
                      <div
                        style={{
                          position: "absolute",
                          left: x,
                          width: BAR_W,
                          textAlign: "center",
                          top: labTop,
                          transform:
                            Math.abs(labRise) > 1e-3
                              ? `translateY(${labRise}px)`
                              : undefined,
                          opacity: lab,
                          fontSize: 16,
                          color: pal.text,
                          fontVariantNumeric: "tabular-nums",
                        }}
                      >
                        {pct(ofFirst(i))}
                      </div>
                      <div
                        style={{
                          position: "absolute",
                          left: x,
                          top: yOf(0) + 14,
                          opacity: lab,
                          transform: `translateY(${(1 - lab) * 6}px)`,
                          whiteSpace: "nowrap",
                        }}
                      >
                        <div style={{ fontSize: 17, color: labelInk(1) }}>
                          {st.label}
                        </div>
                        <div
                          style={{
                            fontSize: 16,
                            color: pal.muted,
                            marginTop: 3,
                            fontVariantNumeric: "tabular-nums",
                          }}
                        >
                          {fmt(value(i))}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div
                style={{
                  position: "absolute",
                  left: tipX,
                  top: tipY,
                  width: tipW,
                  opacity: tipA,
                  transform: `translateY(${(1 - tip) * 12}px) scale(${0.94 + 0.06 * tip})`,
                  transformOrigin: "0% 0%",
                  background: pal.tip,
                  borderRadius: 14,
                  boxShadow: pal.tipShadow,
                  padding: tall ? "16px 18px 14px" : "12px 16px 10px",
                  boxSizing: "border-box",
                }}
              >
                <div style={{ fontSize: 16, color: pal.muted }}>
                  {tt + 1} · {steps[tt].event}
                </div>
                <div
                  style={{
                    display: "flex",
                    alignItems: "baseline",
                    gap: 10,
                    marginTop: tall ? 6 : 4,
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  <span
                    style={{
                      fontSize: tall ? 34 : 30,
                      lineHeight: 1.2,
                      fontWeight: 300,
                      color: pal.text,
                      letterSpacing: "-0.03em",
                    }}
                  >
                    {fmt(stepV)}
                  </span>
                  <span style={{ fontSize: 16, color: pal.muted }}>
                    {pct(fromPrev(tt))} of{" "}
                    {steps[Math.max(0, tt - 1)].label.toLowerCase()}
                  </span>
                </div>
                <div
                  style={{
                    height: 1,
                    background: pal.line,
                    margin: tall ? "14px 0 8px" : "10px 0 6px",
                  }}
                />
                {breakdown.map((b, k) => {
                  const r = sp(
                    tipEl.start +
                      tipEl.beat("rowAt") +
                      k * tipEl.beat("rowStep"),
                    CARD,
                  );
                  return (
                    <div
                      key={b.label}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 12,
                        height: rowH,
                        fontSize: 16,
                        color: pal.text,
                        fontVariantNumeric: "tabular-nums",
                      }}
                    >
                      <span style={{ width: 66 }}>{b.label}</span>
                      <div
                        style={{
                          flex: 1,
                          height: 6,
                          borderRadius: 3,
                          background: pal.track,
                        }}
                      >
                        <div
                          style={{
                            width: `${b.share * 100 * clamp(r, 0, 1.04)}%`,
                            height: "100%",
                            borderRadius: 3,
                            background: withAlpha(accent, 1 - k * 0.28),
                          }}
                        />
                      </div>
                      <span
                        style={{
                          width: 52,
                          textAlign: "right",
                          color: pal.muted,
                        }}
                      >
                        {fmt(stepV * b.share)}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
            <div style={{ opacity: cursorA }}>
              <Cursor
                x={cur.x}
                y={cur.y}
                rest={cursorRest}
                scale={cursorScale}
              />
            </div>
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The funnel dashboard: the panel rises, the bars grow one after another, a
// cursor clicks the variant toggle and each bar morphs to the variant, the
// uplift badge pops, the cursor moves onto a bar and its tooltip opens, then
// the cursor fades out while the camera pushes in the whole time. Frames on
// the 30 fps scene timeline, after `delay` and `speed`. The ids are public: a
// saved `timing` prop refers to them.

export type AnalyticsFunnelElementId =
  | "panel"
  | `bar:${number}`
  | "camera"
  | "cursor"
  | "click"
  | `morph:${number}`
  | "hover"
  | "badge"
  | "tip"
  | "leave";

export interface FunnelStep {
  label: string;
  event: string;
  control: number;
  variant: number;
}

export interface AnalyticsFunnelTimingProps {
  steps?: FunnelStep[];
}

export const DEFAULT_STEPS: FunnelStep[] = [
  {
    label: "Visit",
    event: "Viewed landing page",
    control: 18420,
    variant: 18420,
  },
  { label: "Sign up", event: "Signed up", control: 7920, variant: 8288 },
  {
    label: "Activate",
    event: "Created first project",
    control: 4277,
    variant: 5304,
  },
  { label: "Pay", event: "Started subscription", control: 1540, variant: 1820 },
];

const T = {
  win: 0,
  bars: 8,
  cursorIn: 26,
  click: 50,
  morph: 56,
  badge: 74,
  toHover: 70,
  tip: 96,
  end: 165,
};
/** Frames between one bar (or one bar's morph) and the next. */
const STAGGER = 3;

// The panel fades in over its length and springs up; the headline, total and
// stats rise on its beats. A bar grows on a spring from its start, its label
// fades in from `labelAt`. The click presses `pressAt` before it and flips
// the toggle `toggleAt` after. A morph springs the bar to the variant and
// draws its control line from `ghostAt` to `ghostEnd`. The tooltip's rows
// fill `rowStep` apart from `rowAt`. The camera pushes in until the end.
export const analyticsFunnelTimeline = defineTimeline<
  AnalyticsFunnelElementId,
  AnalyticsFunnelTimingProps
>(({ steps = DEFAULT_STEPS }): TimelineElement<AnalyticsFunnelElementId>[] => {
  const elements: TimelineElement<AnalyticsFunnelElementId>[] = [
    {
      id: "panel",
      lane: "Panel",
      label: "dashboard",
      start: T.win,
      length: 10,
      beats: {
        headAt: 4,
        headEnd: 16,
        bigAt: 6,
        bigEnd: 20,
        totalAt: 8,
        totalEnd: 22,
        statAt: 12,
        statEnd: 24,
        statStep: 3,
      },
    },
  ];
  steps.forEach((st, i) => {
    elements.push({
      id: `bar:${i}`,
      lane: "Bars",
      label: st.label,
      start: T.bars + i * STAGGER,
      length: 18,
      follows: i > 0 ? `bar:${i - 1}` : undefined,
      beats: { labelAt: 6 },
    });
  });
  elements.push(
    {
      id: "camera",
      lane: "Camera",
      label: "push in",
      start: 20,
      length: T.end - 20,
    },
    {
      id: "cursor",
      lane: "Cursor",
      label: "cursor in",
      start: T.cursorIn,
      length: 6,
    },
    {
      id: "click",
      lane: "Cursor",
      label: "toggle variant",
      start: T.click,
      length: T.morph - T.click,
      follows: "cursor",
      beats: { pressAt: -3, toggleAt: 2 },
    },
  );
  steps.forEach((st, i) => {
    elements.push({
      id: `morph:${i}`,
      lane: "Morph",
      label: st.label,
      start: T.morph + i * STAGGER,
      length: 16,
      follows: i > 0 ? `morph:${i - 1}` : "click",
      beats: { ghostAt: 6, ghostEnd: 16, legendAt: 4, legendEnd: 14 },
    });
  });
  elements.push(
    {
      id: "hover",
      lane: "Cursor",
      label: "hover bar",
      start: T.toHover,
      length: T.tip - T.toHover,
      follows: "click",
    },
    {
      id: "badge",
      lane: "Badge",
      label: "uplift",
      start: T.badge,
      length: 10,
      follows: "click",
    },
    {
      id: "tip",
      lane: "Tooltip",
      label: "tooltip",
      start: T.tip,
      length: 8,
      follows: "hover",
      beats: { rowAt: 6, rowStep: 3 },
    },
    {
      id: "leave",
      lane: "Cursor",
      label: "cursor out",
      start: T.end - 20,
      length: 10,
      follows: "tip",
    },
  );
  return elements.sort((a, b) => a.start - b.start);
});
